"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


_STAR = ("star",)
_ANY = ("any",)
_DOUBLE = "**"


def _strip_trailing_spaces(line: str) -> str:
    while line.endswith(" "):
        n = 0
        i = len(line) - 2
        while i >= 0 and line[i] == "\\":
            n += 1
            i -= 1
        if n % 2 == 1:
            break
        line = line[:-1]
    return line


def _compile_segment(seg: str) -> list:
    tokens: list = []
    i, n = 0, len(seg)
    while i < n:
        c = seg[i]
        if c == "*":
            while i < n and seg[i] == "*":
                i += 1
            tokens.append(_STAR)
        elif c == "?":
            tokens.append(_ANY)
            i += 1
        elif c == "\\":
            if i + 1 >= n:
                raise PatternError("dangling backslash")
            tokens.append(("lit", seg[i + 1]))
            i += 2
        elif c == "[":
            i += 1
            negate = False
            if i < n and seg[i] == "!":
                negate = True
                i += 1
            members: list[tuple[str, str]] = []
            first = True
            closed = False

            def read(i: int) -> tuple[str, int]:
                if seg[i] == "\\":
                    if i + 1 >= n:
                        raise PatternError("dangling backslash")
                    return seg[i + 1], i + 2
                return seg[i], i + 1

            while i < n:
                if seg[i] == "]" and not first:
                    closed = True
                    i += 1
                    break
                first = False
                lo, i = read(i)
                if i + 1 < n and seg[i] == "-" and seg[i + 1] != "]":
                    hi, i = read(i + 1)
                    if ord(hi) < ord(lo):
                        raise PatternError("reversed range")
                    members.append((lo, hi))
                else:
                    members.append((lo, lo))
            if not closed:
                raise PatternError("unclosed character class")
            tokens.append(("class", negate, members))
        else:
            tokens.append(("lit", c))
            i += 1
    return tokens


def _match_segment(tokens: list, s: str) -> bool:
    cur = {0}
    # states: token index; handle stars by epsilon closure
    def close(states: set[int]) -> set[int]:
        out = set(states)
        stack = list(states)
        while stack:
            t = stack.pop()
            if t < len(tokens) and tokens[t] == _STAR and t + 1 not in out:
                out.add(t + 1)
                stack.append(t + 1)
        return out

    cur = close(cur)
    for ch in s:
        nxt: set[int] = set()
        for t in cur:
            if t >= len(tokens):
                continue
            tok = tokens[t]
            kind = tok[0]
            if kind == "star":
                nxt.add(t)
            elif kind == "any":
                nxt.add(t + 1)
            elif kind == "lit":
                if tok[1] == ch:
                    nxt.add(t + 1)
            else:
                inside = any(lo <= ch <= hi for lo, hi in tok[2])
                if inside != tok[1]:
                    nxt.add(t + 1)
        cur = close(nxt)
        if not cur:
            return False
    return len(tokens) in cur


def _compile(line: str):
    line = _strip_trailing_spaces(line)
    if not line or line.startswith("#"):
        return None
    negate = False
    if line.startswith("!"):
        negate = True
        line = line[1:]
    dir_only = False
    if line.endswith("/"):
        dir_only = True
        line = line[:-1]
    if not line:
        return None
    anchored = "/" in line
    if line.startswith("/"):
        line = line[1:]
    segs = line.split("/")
    compiled = []
    for seg in segs:
        if seg == _DOUBLE and anchored:
            compiled.append(_DOUBLE)
        else:
            compiled.append(_compile_segment(seg))
    return negate, dir_only, anchored, compiled


def _match_path(segs: list, parts: list[str]) -> bool:
    ns, np_ = len(segs), len(parts)
    memo: dict[tuple[int, int], bool] = {}

    def go(i: int, j: int) -> bool:
        if i == ns:
            return j == np_
        key = (i, j)
        if key in memo:
            return memo[key]
        seg = segs[i]
        if seg == _DOUBLE:
            if i == ns - 1:
                res = j < np_
            else:
                res = any(go(i + 1, k) for k in range(j, np_ + 1))
        else:
            res = j < np_ and _match_segment(seg, parts[j]) and go(i + 1, j + 1)
        memo[key] = res
        return res

    return go(0, 0)


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled = [c for c in (_compile(p) for p in patterns) if c is not None]
    parts = path.split("/")
    result = False
    for negate, dir_only, anchored, segs in compiled:
        if dir_only and not is_dir:
            continue
        if anchored:
            matched = _match_path(segs, parts)
        else:
            matched = _match_segment(segs[0], parts[-1])
        if matched:
            result = not negate
    return result
